def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_opp += 1
            if opp.get('hp', 0) <= 4 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev.get('bid', 0.0)))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = max(0.0, min(1.0, (20.0 - supply) / 5.0))
    pressure = 0.0
    pressure += 0.9 * scarcity
    pressure += 0.2 * max(0, len(alive) - 2)
    pressure += 0.15 * urgent_opp
    pressure += 0.1 * rich_opp

    if hp <= 2 or no_water_days >= 2:
        bid = max(110.0, highest_prev + 8.0, avg_prev + 10.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(88.0, highest_prev + 4.0, avg_prev + 3.0)
    else:
        if highest_prev >= 150.0:
            bid = 28.0 + 10.0 * scarcity
        elif highest_prev >= 110.0:
            bid = 42.0 + 18.0 * pressure
        else:
            bid = 48.0 + 22.0 * pressure
            if scarcity > 0.45:
                bid = max(bid, highest_prev + 2.5)

    if supply >= 23.0 and hp >= 6 and no_water_days == 0:
        bid *= 0.72
    elif supply >= 20.0 and hp >= 5 and no_water_days == 0:
        bid *= 0.85

    reserve = 0.0
    if hp >= 6 and no_water_days == 0:
        reserve = 35.0
    elif hp >= 4:
        reserve = 15.0

    cap = budget - reserve
    if hp <= 3 or no_water_days >= 1:
        cap = budget
    cap = max(0.0, cap)

    bid = min(bid, cap)

    if bid <= 0 and budget > 0:
        bid = min(budget, 8.0)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 120.0 if budget >= 120.0 else budget))

    return float(max(0.0, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Yesterday bids (immediate reaction)
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine how scarce water is relative to requirement
    # If supply is close to requirement, we must bid more to beat others.
    scarcity_ratio = supply / float(WATER_REQ)  # e.g., 15/9 ~ 1.67

    # Baseline bid: aim around a fraction of DAILY_SALARY, adjusted by scarcity and my HP.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # If I'm already in danger, bid aggressively.
    if hp <= 2 or no_water_days >= 2:
        cap = min(budget, DAILY_SALARY * 0.95)
        # If others were very aggressive yesterday, go higher within cap.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            return float(min(cap, DAILY_SALARY * 0.95))
        return float(cap)

    # If yesterday had very high bids, increase slightly to avoid being outbid.
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        base = DAILY_SALARY * 0.75
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.52

    # Scarcity adjustment: lower scarcity_ratio -> higher bid.
    # scarcity_ratio range roughly 1.67..2.78 for supply 15..25 with WATER_REQ=9
    if scarcity_ratio <= 1.75:
        base *= 1.15
    elif scarcity_ratio >= 2.5:
        base *= 0.92

    # Budget safety: don't overspend early; keep some reserve.
    # Reserve target: at least ~30% of budget or one more day salary.
    reserve = max(0.3 * budget, DAILY_SALARY * 0.35)
    max_affordable = max(0.0, budget - reserve)

    bid = min(max_affordable, base)

    # If computed bid is too low to matter, ensure a minimum meaningful bid.
    # But never exceed budget.
    min_bid = DAILY_SALARY * 0.35
    if bid < min_bid:
        bid = min(budget, min_bid)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if supply < WATER_REQ * 1.5:
        return min(my_status['budget'], avg_prev_bid * 1.1)

    return min(my_status['budget'], max(40.0, avg_prev_bid * 0.95))
